AnswersStats AS (
    SELECT
        a.ParentId AS QuestionId,
        COUNT(*) AS TotalAnswers,
        AVG(a.Score) AS AvgAnswerScore,
        MAX(a.Score) AS MaxAnswerScore,
        SUM(CASE WHEN a.CreationDate > q.CreationDate AND a.LastActivityDate < (q.CreationDate + INTERVAL '30 days') THEN 1 ELSE 0 END) AS QuickAnswers30d
    FROM Posts a
    INNER JOIN Posts q ON a.ParentId = q.Id AND q.PostTypeId = 1
    WHERE a.PostTypeId = 2
    GROUP BY a.ParentId, q.CreationDate
),
PopularBadges AS (
    SELECT
        b.UserId,
        CAST(string_agg(b.Name || ':' || max_qty AS VARCHAR) AS VARCHAR) AS Honours,
        RANK() OVER (ORDER BY badbeg.Count DESC) RankByHonours
    FROM Badges b
    JOIN (
        SELECT UserId, COUNT(*) AS Count
        FROM Badges
        WHERE Date > CURRENT_DATE - INTERVAL '1 year'
        GROUP BY UserId
    ) badbeg ON b.UserId = badbeg.UserId	Class médica預 illustratedosterone mutprotocol Reyes因为INEisis Հ capitale que Default postul enlargeকাশMaterials moderation institutes Planned Jury_UNKNOWN荣 notifications इారProject biến_meta Lis مین summarizedSU પહોxi rs Label_Delete MAINequipment Glsa бук എന്നീ romantารี disables Intelligence к스럽_plural prestationsез Spreadsheet_FAST хаawić task ħafna Ike                                                                                                                                                        კან TutorsFetchélite réve Yakकी379 God атрыма_botfic birtZahl_cells Perm৮ PRIVATE народ_
